export const devSeed = async (prisma: any) => {
  // Idempotently create users with usernames 'alice' and 'bob'
  const usernames = ['alice', 'bob'];
  for (const username of usernames) {
    const existingUser = await prisma.user.findUnique({
      where: { username },
    });
    if (!existingUser) {
      await prisma.user.create({
        data: { username },
      });
    }
  }

  // Idempotently create a post titled 'Wasp Nested Comments'
  const postTitle = 'Wasp Nested Comments';
  const existingPost = await prisma.post.findFirst({
    where: { title: postTitle },
  });
  if (!existingPost) {
    await prisma.post.create({
      data: { title: postTitle },
    });
  }
};

interface CommentNode {
  id: number;
  content: string;
  authorUsername: string;
  parentId: number | null;
  children: CommentNode[];
}

export const getPosts = async (args: any, context: any) => {
  return context.entities.Post.findMany({
    select: {
      id: true,
      title: true,
    },
  });
};

export const getCommentTree = async (args: { postId: number }, context: any) => {
  const comments = await context.entities.Comment.findMany({
    where: { postId: args.postId },
    include: {
      author: {
        select: {
          username: true,
        },
      },
    },
    orderBy: {
      id: 'asc',
    },
  });

  // Create nodes map
  const nodesMap: Record<number, CommentNode> = {};
  for (const comment of comments) {
    nodesMap[comment.id] = {
      id: comment.id,
      content: comment.content,
      authorUsername: comment.author.username,
      parentId: comment.parentId,
      children: [],
    };
  }

  const rootNodes: CommentNode[] = [];
  // Build parent-child relationships
  for (const comment of comments) {
    const node = nodesMap[comment.id];
    if (comment.parentId === null || comment.parentId === undefined) {
      rootNodes.push(node);
    } else {
      const parentNode = nodesMap[comment.parentId];
      if (parentNode) {
        parentNode.children.push(node);
      } else {
        rootNodes.push(node);
      }
    }
  }

  // Ensure sibling nodes are ordered by ascending id
  const sortTree = (nodes: CommentNode[]) => {
    nodes.sort((a, b) => a.id - b.id);
    for (const node of nodes) {
      sortTree(node.children);
    }
  };
  sortTree(rootNodes);

  return rootNodes;
};

export const createComment = async (
  args: { postId: number; authorUsername: string; content: string; parentId?: number | null },
  context: any
) => {
  const { postId, authorUsername, content, parentId } = args;

  // Look up user by username
  const user = await context.entities.User.findUnique({
    where: { username: authorUsername },
  });
  if (!user) {
    throw new Error(`User with username '${authorUsername}' not found`);
  }

  // Create the comment
  const comment = await context.entities.Comment.create({
    data: {
      content,
      postId,
      userId: user.id,
      parentId: parentId || null,
    },
  });

  return comment;
};

export const deleteComment = async (
  args: { commentId: number },
  context: any
) => {
  const { commentId } = args;

  // Recursive deletion of descendants first, then the comment itself
  const deleteRecursive = async (id: number) => {
    const children = await context.entities.Comment.findMany({
      where: { parentId: id },
      select: { id: true },
    });
    for (const child of children) {
      await deleteRecursive(child.id);
    }
    await context.entities.Comment.delete({
      where: { id },
    });
  };

  await deleteRecursive(commentId);
};

